import{J as e,n as t,ot as n,q as r}from"./chunks/framework.DStH8c-G.js";var i=JSON.parse(`{"title":"Class: Level","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Class: Level"}],["meta",{"property":"og:description","content":""}],["meta",{"property":"og:url","content":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/Level"}],["link",{"rel":"canonical","href":"https://jsprismarine.dev/api/@jsprismarine/prismarine/classes/Level"}]],"editSource":{"kind":"folder","url":"https://github.com/JSPrismarine/JSPrismarine/tree/master/packages/prismarine/src"}},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/Level.md","filePath":"api/@jsprismarine/prismarine/classes/Level.md","lastUpdated":1794383204000}`),a={name:`api/@jsprismarine/prismarine/classes/Level.md`};function o(t,i,a,o,s,c){return n(),r(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">API reference</a> / <a href="./../">@jsprismarine/prismarine</a> / Level</p><h1 id="class-level" tabindex="-1">Class: Level <a class="header-anchor" href="#class-level" aria-label="Permalink to “Class: Level”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L141" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:141</a></p><p>One save: a seed, a provider, a dimension set, and the state Bedrock keeps once per level.</p><p><a href="#enable">Level.enable</a> opens the provider and reads the saved state; <a href="#world">Level.world</a> builds a dimension&#39;s world when it is first asked for; <a href="#update">Level.update</a> advances the clock once per server tick and ticks every loaded world; <a href="#disable">Level.disable</a> saves and closes.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new Level</strong>(<code>options</code>): <code>Level</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L201" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:201</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="options" tabindex="-1">options <a class="header-anchor" href="#options" aria-label="Permalink to “options”">​</a></h5><p><a href="./../#leveloptions"><code>LevelOptions</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Level</code></p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When the stems have no <code>minecraft:overworld</code>, a stem names a dimension type that <code>dimensionTypes</code> does not carry, or two stems bind one type.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h3><blockquote><p><code>readonly</code> <strong>name</strong>: <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L143" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:143</a></p><p>The folder name under <code>worlds/</code>, which is also the <code>worlds.&lt;name&gt;</code> key.</p><hr><h3 id="seed" tabindex="-1">seed <a class="header-anchor" href="#seed" aria-label="Permalink to “seed”">​</a></h3><blockquote><p><code>readonly</code> <strong>seed</strong>: <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L146" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:146</a></p><p>The seed every generated chunk, structure placement and carver in this level comes from.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="capturereplayinitialstate" tabindex="-1">captureReplayInitialState() <a class="header-anchor" href="#capturereplayinitialstate" aria-label="Permalink to “captureReplayInitialState()”">​</a></h3><blockquote><p><strong>captureReplayInitialState</strong>(): <code>Promise</code>&lt;<a href="./../#replayinitialstatemanifest"><code>ReplayInitialStateManifest</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L609" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:609</a></p><p>Saves and captures the provider-backed initial state for a replay.</p><p>The provider snapshot includes persisted records for loaded and unloaded chunks. Restore it into a fresh provider before that provider opens, then validate and restore the random state with <a href="#restorereplayrandomstate">Level.restoreReplayRandomState</a>.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../#replayinitialstatemanifest"><code>ReplayInitialStateManifest</code></a>&gt;</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>When the provider cannot capture replay snapshots or persisted state cannot be saved.</p><hr><h3 id="customdimensiondefinitions" tabindex="-1">customDimensionDefinitions() <a class="header-anchor" href="#customdimensiondefinitions" aria-label="Permalink to “customDimensionDefinitions()”">​</a></h3><blockquote><p><strong>customDimensionDefinitions</strong>(): <code>object</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L521" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:521</a></p><p>The <code>DimensionDefinition</code> of every custom dimension, for <code>DimensionDataPacket</code>.</p><p>A dimension type the Bedrock overlay does not list is one the client has never heard of, so it has to be told the bounds and the id the level chose, from <a href="./../#first-custom-dimension-id">FIRST_CUSTOM_DIMENSION_ID</a> in stem order. The generator type is <code>Void</code>, as Dragonfly sends it: the client generates nothing for a dimension a server feeds it.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>object</code>[]</p><p>One entry per custom dimension type, in stem order; empty for a vanilla level.</p><hr><h3 id="dimensiontypeof" tabindex="-1">dimensionTypeOf() <a class="header-anchor" href="#dimensiontypeof" aria-label="Permalink to “dimensionTypeOf()”">​</a></h3><blockquote><p><strong>dimensionTypeOf</strong>(<code>dimensionId</code>): <a href="./../#dimensiontype"><code>DimensionType</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L337" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:337</a></p><p>The dimension type a stem binds.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="dimensionid" tabindex="-1">dimensionId <a class="header-anchor" href="#dimensionid" aria-label="Permalink to “dimensionId”">​</a></h5><p><code>string</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#dimensiontype"><code>DimensionType</code></a></p><h4 id="throws-2" tabindex="-1">Throws <a class="header-anchor" href="#throws-2" aria-label="Permalink to “Throws”">​</a></h4><p>When no stem has that dimension id.</p><hr><h3 id="getdimensiontypes" tabindex="-1">getDimensionTypes() <a class="header-anchor" href="#getdimensiontypes" aria-label="Permalink to “getDimensionTypes()”">​</a></h3><blockquote><p><strong>getDimensionTypes</strong>(): <code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../#dimensiontype"><code>DimensionType</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L323" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:323</a></p><p>The dimension types the stems use, by type id, with their Bedrock ids resolved.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../#dimensiontype"><code>DimensionType</code></a>&gt;</p><hr><h3 id="getgamerulemanager" tabindex="-1">getGameRuleManager() <a class="header-anchor" href="#getgamerulemanager" aria-label="Permalink to “getGameRuleManager()”">​</a></h3><blockquote><p><strong>getGameRuleManager</strong>(): <code>GameRuleManager</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L591" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:591</a></p><p>The level&#39;s game rules, one set for every world of the save.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>GameRuleManager</code></p><hr><h3 id="getgeneratorfactories" tabindex="-1">getGeneratorFactories() <a class="header-anchor" href="#getgeneratorfactories" aria-label="Permalink to “getGeneratorFactories()”">​</a></h3><blockquote><p><strong>getGeneratorFactories</strong>(): <a href="./GeneratorFactories.html"><code>GeneratorFactories</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L328" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:328</a></p><p>The generator kinds this level builds its stems with.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./GeneratorFactories.html"><code>GeneratorFactories</code></a></p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L303" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:303</a></p><p>The level&#39;s folder name, which is what the tick loop and the logs call it.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getplayerdata" tabindex="-1">getPlayerData() <a class="header-anchor" href="#getplayerdata" aria-label="Permalink to “getPlayerData()”">​</a></h3><blockquote><p><strong>getPlayerData</strong>(<code>key</code>): <code>Promise</code>&lt;<code>Partial</code>&lt;<a href="./../#worldplayerdata"><code>WorldPlayerData</code></a>&gt; | <code>null</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L968" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:968</a></p><p>The record for one player, from the provider&#39;s player storage or the fallback JSON file.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="key" tabindex="-1">key <a class="header-anchor" href="#key" aria-label="Permalink to “key”">​</a></h5><p><code>string</code></p><p>What the record is filed under; see <code>World.playerDataKey</code>.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Partial</code>&lt;<a href="./../#worldplayerdata"><code>WorldPlayerData</code></a>&gt; | <code>null</code>&gt;</p><p>The record, or null when this save has none for the key. A provider read that fails is logged and falls through to the file.</p><hr><h3 id="getprovider" tabindex="-1">getProvider() <a class="header-anchor" href="#getprovider" aria-label="Permalink to “getProvider()”">​</a></h3><blockquote><p><strong>getProvider</strong>(): <a href="./BaseProvider.html"><code>BaseProvider</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L313" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:313</a></p><p>The one provider every dimension of this save reads and writes through.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./BaseProvider.html"><code>BaseProvider</code></a></p><hr><h3 id="getserver" tabindex="-1">getServer() <a class="header-anchor" href="#getserver" aria-label="Permalink to “getServer()”">​</a></h3><blockquote><p><strong>getServer</strong>(): <a href="./Server.html"><code>Server</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L308" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:308</a></p><p>The server this level belongs to.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Server.html"><code>Server</code></a></p><hr><h3 id="getspawn" tabindex="-1">getSpawn() <a class="header-anchor" href="#getspawn" aria-label="Permalink to “getSpawn()”">​</a></h3><blockquote><p><strong>getSpawn</strong>(): <a href="./../../math/classes/Vector3.html"><code>Vector3</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L697" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:697</a></p><p>The world spawn if it is known, and null while it is not.</p><p>Bedrock&#39;s <code>SpawnX/Y/Z</code> is one point per save and it is in the Overworld, so the Overworld world searches for it and every world reads it from here.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a> | <code>null</code></p><hr><h3 id="getstems" tabindex="-1">getStems() <a class="header-anchor" href="#getstems" aria-label="Permalink to “getStems()”">​</a></h3><blockquote><p><strong>getStems</strong>(): <code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../../worldgen/#levelstem"><code>LevelStem</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L318" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:318</a></p><p>The resolved level stems by dimension id, in the order the level was given them.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>ReadonlyMap</code>&lt;<code>string</code>, <a href="./../../worldgen/#levelstem"><code>LevelStem</code></a>&gt;</p><hr><h3 id="getticks" tabindex="-1">getTicks() <a class="header-anchor" href="#getticks" aria-label="Permalink to “getTicks()”">​</a></h3><blockquote><p><strong>getTicks</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L581" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:581</a></p><p>The level&#39;s clock, in ticks since it was created.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getweather" tabindex="-1">getWeather() <a class="header-anchor" href="#getweather" aria-label="Permalink to “getWeather()”">​</a></h3><blockquote><p><strong>getWeather</strong>(): <code>WorldWeather</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L596" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:596</a></p><p>The level&#39;s weather: one cycle for the whole save, rendered where there is a sky.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>WorldWeather</code></p><hr><h3 id="isclosed" tabindex="-1">isClosed() <a class="header-anchor" href="#isclosed" aria-label="Permalink to “isClosed()”">​</a></h3><blockquote><p><strong>isClosed</strong>(): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L707" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:707</a></p><p>Whether <a href="#disable">Level.disable</a> has closed the provider, after which nothing can be read or written.</p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><hr><h3 id="legacyentities" tabindex="-1">legacyEntities() <a class="header-anchor" href="#legacyentities" aria-label="Permalink to “legacyEntities()”">​</a></h3><blockquote><p><strong>legacyEntities</strong>(): readonly <code>LegacyWorldEntity</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L715" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:715</a></p><p>Entity snapshots the save kept outside its chunks, which a provider without actor storage wrote for the Overworld. Empty once a chunk-storing provider owns the save.</p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p>readonly <code>LegacyWorldEntity</code>[]</p><hr><h3 id="loadedworld" tabindex="-1">loadedWorld() <a class="header-anchor" href="#loadedworld" aria-label="Permalink to “loadedWorld()”">​</a></h3><blockquote><p><strong>loadedWorld</strong>(<code>dimensionId</code>): <a href="./World.html"><code>World</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L403" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:403</a></p><p>The world of one dimension if the level has built it, whether or not its enabling has finished; undefined otherwise. Nothing is built.</p><p>The one accessor that answers a world mid-enable, which is how <code>WorldManager</code> names the default world while its start region generates. <a href="#worlds">Level.worlds</a> lists ready worlds only.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="dimensionid-1" tabindex="-1">dimensionId <a class="header-anchor" href="#dimensionid-1" aria-label="Permalink to “dimensionId”">​</a></h5><p><code>string</code></p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./World.html"><code>World</code></a> | <code>undefined</code></p><hr><h3 id="readyworldoftype" tabindex="-1">readyWorldOfType() <a class="header-anchor" href="#readyworldoftype" aria-label="Permalink to “readyWorldOfType()”">​</a></h3><blockquote><p><strong>readyWorldOfType</strong>(<code>typeId</code>): <a href="./World.html"><code>World</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L425" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:425</a></p><p>The ready world whose dimension type has this id, or undefined.</p><p><a href="#worlds">Level.worlds</a> filtered by type, without the iterator: the content adapter asks on every block it reads, which made the lookup one of the busier calls of a tick.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="typeid" tabindex="-1">typeId <a class="header-anchor" href="#typeid" aria-label="Permalink to “typeId”">​</a></h5><p><code>string</code></p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./World.html"><code>World</code></a> | <code>undefined</code></p><hr><h3 id="restorereplayrandomstate" tabindex="-1">restoreReplayRandomState() <a class="header-anchor" href="#restorereplayrandomstate" aria-label="Permalink to “restoreReplayRandomState()”">​</a></h3><blockquote><p><strong>restoreReplayRandomState</strong>(<code>manifest</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L660" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:660</a></p><p>Verifies a matching initial boundary and restores only its random streams.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="manifest" tabindex="-1">manifest <a class="header-anchor" href="#manifest" aria-label="Permalink to “manifest”">​</a></h5><p><a href="./../#replayinitialstatemanifest"><code>ReplayInitialStateManifest</code></a></p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="save" tabindex="-1">save() <a class="header-anchor" href="#save" aria-label="Permalink to “save()”">​</a></h3><blockquote><p><strong>save</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L826" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:826</a></p><p>Writes the whole level: every loaded world&#39;s players and chunks, then the level data.</p><h4 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="saveleveldata" tabindex="-1">saveLevelData() <a class="header-anchor" href="#saveleveldata" aria-label="Permalink to “saveLevelData()”">​</a></h3><blockquote><p><strong>saveLevelData</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L839" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:839</a></p><p>Writes the level&#39;s own state through the provider: the spawn, rules, weather and stems into the provider&#39;s record, and the spawn, clock, generator and Nether scale into <code>level.dat</code>.</p><p>A level whose spawn is still unknown writes everything else and leaves the stored spawn where it is. Overwriting a real spawn point with a guess would be worse than the gap.</p><h4 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="saveplayerdata" tabindex="-1">savePlayerData() <a class="header-anchor" href="#saveplayerdata" aria-label="Permalink to “savePlayerData()”">​</a></h3><blockquote><p><strong>savePlayerData</strong>(<code>key</code>, <code>data</code>, <code>requireSuccess?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L996" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:996</a></p><p>Writes one player&#39;s record, through the provider when it stores players and into the fallback JSON file otherwise.</p><p>Declined once the level has closed. A shutdown kicks everyone, and each client&#39;s connection closes some time after the provider has gone, so a save arrives once more per player with nothing left to write to; the shutdown&#39;s own save wrote them while they were still online.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="key-1" tabindex="-1">key <a class="header-anchor" href="#key-1" aria-label="Permalink to “key”">​</a></h5><p><code>string</code></p><h5 id="data" tabindex="-1">data <a class="header-anchor" href="#data" aria-label="Permalink to “data”">​</a></h5><p><a href="./../#worldplayerdata"><code>WorldPlayerData</code></a></p><h5 id="requiresuccess" tabindex="-1">requireSuccess? <a class="header-anchor" href="#requiresuccess" aria-label="Permalink to “requireSuccess?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>Propagate a persistence error when creating a replay checkpoint.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setspawn" tabindex="-1">setSpawn() <a class="header-anchor" href="#setspawn" aria-label="Permalink to “setSpawn()”">​</a></h3><blockquote><p><strong>setSpawn</strong>(<code>at</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L702" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:702</a></p><p>Sets the world spawn; see <a href="#getspawn">Level.getSpawn</a>.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setticks" tabindex="-1">setTicks() <a class="header-anchor" href="#setticks" aria-label="Permalink to “setTicks()”">​</a></h3><blockquote><p><strong>setTicks</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L586" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:586</a></p><p>Sets the clock, which is what <code>/time set</code> does.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick" tabindex="-1">tick <a class="header-anchor" href="#tick" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="storeddragonfightstate" tabindex="-1">storedDragonFightState() <a class="header-anchor" href="#storeddragonfightstate" aria-label="Permalink to “storedDragonFightState()”">​</a></h3><blockquote><p><strong>storedDragonFightState</strong>(): <code>DragonFightState</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L896" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:896</a></p><p>The dragon fight the save held, which the End world&#39;s fight starts from.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><code>DragonFightState</code> | <code>undefined</code></p><hr><h3 id="storedraids" tabindex="-1">storedRaids() <a class="header-anchor" href="#storedraids" aria-label="Permalink to “storedRaids()”">​</a></h3><blockquote><p><strong>storedRaids</strong>(): <code>RaidRecord</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L879" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:879</a></p><p>The raids the save held, which the Overworld&#39;s raid manager starts from.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>RaidRecord</code>[]</p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>(<code>tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L805" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:805</a></p><p>One server tick: the clock advances once, the weather cycle runs, and every loaded world updates against the new tick.</p><p>The weather goes before the worlds for the reason <code>ServerLevel.tick</code> runs <code>advanceWeatherCycle</code> before its tick lists: a fire scheduled this tick should be put out by rain that started this tick.</p><p>The worlds tick one after another in stem order, as <code>MinecraftServer.tickChildren</code> walks its levels, rather than interleaved. An entity that leaves one world for another during its update is then in exactly one world&#39;s roster at any point of the tick; a world ticked later skips an arrival that was already ticked this tick.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-1" tabindex="-1">tick <a class="header-anchor" href="#tick-1" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><p>The server&#39;s tick counter, which the worlds pace their own work by.</p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="world" tabindex="-1">world() <a class="header-anchor" href="#world" aria-label="Permalink to “world()”">​</a></h3><blockquote><p><strong>world</strong>(<code>dimensionId</code>): <code>Promise</code>&lt;<a href="./World.html"><code>World</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L360" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:360</a></p><p>The world of one dimension, built and enabled on first request.</p><p>The first call for a dimension asks the factories for the stem&#39;s generator, builds the world and enables it; every later call answers the same instance once that enabling has finished. Two overlapping first calls share one build. A world whose enabling failed is forgotten, so the call after the failure builds it again rather than answering the same rejection for the life of the level. Only an <code>eager</code> stem&#39;s world generates its start region here; a lazy one is built from inside a server tick and leaves its first chunks to whoever arrives.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="dimensionid-2" tabindex="-1">dimensionId <a class="header-anchor" href="#dimensionid-2" aria-label="Permalink to “dimensionId”">​</a></h5><p><code>string</code></p><p>The stem&#39;s key, <code>minecraft:the_nether</code> for the Nether. The vanilla stems share their dimension type&#39;s id.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./World.html"><code>World</code></a>&gt;</p><h4 id="throws-3" tabindex="-1">Throws <a class="header-anchor" href="#throws-3" aria-label="Permalink to “Throws”">​</a></h4><p>Before <a href="#enable">Level.enable</a>, when no stem has that id, or when the stem&#39;s generator cannot be built or the world cannot be enabled.</p><hr><h3 id="worlds" tabindex="-1">worlds() <a class="header-anchor" href="#worlds" aria-label="Permalink to “worlds()”">​</a></h3><blockquote><p><strong>worlds</strong>(): <code>IterableIterator</code>&lt;<a href="./World.html"><code>World</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L413" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:413</a></p><p>Every world whose enabling has finished, in build order.</p><p>A world still enabling is left out: it has no players, it must not tick before its start region is settled, and <code>WorldManager.getWorldByDimension</code> promises loaded worlds only.</p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><code>IterableIterator</code>&lt;<a href="./World.html"><code>World</code></a>&gt;</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L948" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:948</a></p><p>Saves and closes: every world stops and writes itself, the level data goes out once more, and the provider is closed last, once nothing is left that could ask it for anything.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/c9c1c0a02ef12b11dcc776f76ca5e349269543e8/packages/prismarine/src/world/Level.ts#L729" target="_blank" rel="noreferrer">prismarine/src/world/Level.ts:729</a></p><p>Opens the provider, reads the saved state and builds the eager worlds.</p><p>The eager worlds are constructed before the first <code>await</code>, so a caller that starts this and needs one of them at once, as <code>WorldManager</code> needs the default world, finds it through <a href="#loadedworld">Level.loadedWorld</a> while the provider is still opening.</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p>`,301)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};